  <script>
    (function () {
      const root = document.querySelector(".rt-pacs-page");
      if (!root) return;

      const buttons = root.querySelectorAll(".rtp-tab-btn");
      const panels = root.querySelectorAll(".rtp-tab-panel");

      buttons.forEach(function (button) {
        button.addEventListener("click", function () {
          const tab = button.getAttribute("data-tab");

          buttons.forEach(function (btn) {
            btn.classList.remove("active");
          });

          panels.forEach(function (panel) {
            panel.classList.remove("active");
          });

          button.classList.add("active");

          const activePanel = root.querySelector('[data-panel="' + tab + '"]');
          if (activePanel) activePanel.classList.add("active");
        });
      });

      const animated = root.querySelectorAll(".rtp-stat, .rtp-quick-box, .rtp-panel, .rtp-media-card, .rtp-feature, .rtp-tab-panel, .rtp-audience, .rtp-study-card, .rtp-cost-box, .rtp-related-card");

      if (!("IntersectionObserver" in window)) {
        animated.forEach(function (item) {
          item.style.opacity = "1";
          item.style.transform = "translateY(0)";
        });
        return;
      }

      animated.forEach(function (item) {
        item.style.opacity = "0";
        item.style.transform = "translateY(18px)";
        item.style.transition = "opacity .55s ease, transform .55s ease";
      });

      const observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.style.opacity = "1";
            entry.target.style.transform = "translateY(0)";
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.12 });

